import pandas as pd
def clean(df):
    df = df.drop_duplicates(subset=["Order_ID"], keep="first")
    df["Category"] = df["Category"].str.title()
    df["Category"] = df["Category"].replace({"Furnture": "Furniture"})
    return df
def answer(df):
    counts = df.groupby("Category").size().to_dict()
    return {k: v for k, v in counts.items() if pd.notna(k)}
